// This file defines condition codes for the Cucaracha target.
// Enums and lookup tables are generated by TableGen.
//
//===----------------------------------------------------------------------===//

#ifndef LLVM_LIB_TARGET_CUCARACHA_CUCARACHACONDITIONCODES_H
#define LLVM_LIB_TARGET_CUCARACHA_CUCARACHACONDITIONCODES_H

#include "llvm/ADT/ArrayRef.h"
#include "llvm/ADT/StringRef.h"
#include <cstdint>

namespace llvm {
namespace CucarachaCC {

//===----------------------------------------------------------------------===//
// TableGen-generated code
//===----------------------------------------------------------------------===//

// Forward declare the struct used by TableGen's GenericTable
struct CondCodeInfo {
  uint8_t Code;
  const char *Name;
  const char *OppositeName;
  const char *TestExpr;
};

// CPSR Flags enum
#define GET_CPSRFlagsList_DECL
#include "CucarachaGenSearchableTables.inc"
#undef GET_CPSRFlagsList_DECL

// Condition Code enum
#define GET_CucarachaCondCodesList_DECL
#include "CucarachaGenSearchableTables.inc"
#undef GET_CucarachaCondCodesList_DECL

// Lookup tables implementation
#define GET_CucarachaCondCodeLookup_IMPL
#include "CucarachaGenSearchableTables.inc"
#undef GET_CucarachaCondCodeLookup_IMPL

// Type alias for cleaner code
using CondCode = CucarachaCondCodesList;

//===----------------------------------------------------------------------===//
// Helper functions using TableGen lookups
//===----------------------------------------------------------------------===//

/// Get the opposite condition code
inline CondCode getOppositeCondition(CondCode Cond) {
  if (const auto *Info = lookupCondCodeByCode(static_cast<unsigned>(Cond))) {
    if (const auto *Opposite = CucarachaCondCodeByName(Info->OppositeName))
      return static_cast<CondCode>(Opposite->Code);
  }
  return CondCode::COND_INVALID;
}

} // namespace CucarachaCC
} // namespace llvm

#endif // LLVM_LIB_TARGET_CUCARACHA_CUCARACHACONDITIONCODES_H
